// Handle both string and object input from the AI agent
let raw = $input;

// If it's an object (most common in toolCode nodes), extract the string
if (typeof raw === 'object' && raw !== null) {
  // n8n toolCode receives input as the first item's json.input
  raw = $input.first()?.json?.input ?? $input.first()?.json?.query ?? JSON.stringify($input);
}

const duration = parseInt(String(raw).trim(), 10);

if (isNaN(duration) || duration <= 0) {
  return JSON.stringify({ error: "Invalid duration: " + raw });
}

// Calculate Start Date
const start = new Date();
const startY = start.getFullYear();
const startM = String(start.getMonth() + 1).padStart(2, '0');
const startD = String(start.getDate()).padStart(2, '0');

// Calculate End Date
const end = new Date();
end.setMonth(end.getMonth() + duration);
const endY = end.getFullYear();
const endM = String(end.getMonth() + 1).padStart(2, '0');
const endD = String(end.getDate()).padStart(2, '0');

return JSON.stringify({
  start_date: `${startY}-${startM}-${startD}`,
  end_date:   `${endY}-${endM}-${endD}`
});

// Get the raw text from the AI agent
const text = $('Supervisor agent').first().json.output || "";

// Check if it contains HTML tags
const isHTML = /<\/?[a-z][\s\S]*>/i.test(text);

// Prepare the base JSON output
let result = {
  json: { 
    is_html: isHTML 
  }
};

// Only generate the file if it is actually HTML
if (isHTML) {
  const date = new Date().toISOString().split('T')[0];
  result.binary = {
    data: {
      data: Buffer.from(text).toString('base64'),
      mimeType: 'text/html',
      fileName: `report-${date}.html`
    }
  };
}

return result;
